const C={body:'#4f7cff',far:'#9bb3f5',shorts:'#1c2a55',skin:'#e7c4a0',hair:'#2a2118',hl:'rgba(255,70,70,.62)',gear:'#aab2c3',plate:'#2b2f3a',floor:'#c4cad8',line:'#8a93a8'};
const f1=n=>(Math.round(n*10)/10);
const seg=(a,b,w,c)=>`<line x1="${f1(a[0])}" y1="${f1(a[1])}" x2="${f1(b[0])}" y2="${f1(b[1])}" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const circ=(p,r,c,ex='')=>`<circle cx="${f1(p[0])}" cy="${f1(p[1])}" r="${r}" fill="${c}" ${ex}/>`;
function ell(p,rx,ry,ang,c){return `<ellipse cx="${f1(p[0])}" cy="${f1(p[1])}" rx="${rx}" ry="${ry}" transform="rotate(${f1(ang)} ${f1(p[0])} ${f1(p[1])})" fill="${c}"/>`}
