  s+=seg(P.HR,P.knR,11,C.shorts)+seg(P.knR,P.anR,9,C.body)+circ(P.anR,5,C.hair);
  s+=`<polygon points="${f1(P.SL[0])},${f1(P.SL[1])} ${f1(P.SR[0])},${f1(P.SR[1])} ${f1(P.HR[0]+2)},${f1(P.HR[1])} ${f1(P.HL[0]-2)},${f1(P.HL[1])}" fill="${C.body}"/>`;
